from urllib.parse import parse_qs, unquote
import urllib.parse

def parse_query(value):
    # Check for malformed percent escapes first
    try:
        # This will raise ValueError for malformed percent escapes
        unquote(value, encoding='utf-8', errors='strict')
    except (ValueError, KeyError):
        raise ValueError("Malformed percent escape")

    # Parse the query string
    parsed = parse_qs(value, keep_blank_values=True)

    # Return the last value for repeated keys
    return {key: values[-1] for key, values in parsed.items()}

