def parse_query(value):
    # Check for malformed percent escapes first by attempting to parse
    # We need to manually check for invalid percent encoding
    if value:
        # Find all %XX patterns and validate them
        i = 0
        while i < len(value):
            if value[i] == '%':
                # Check if there are enough characters for a hex pair
                if i + 2 >= len(value):
                    raise ValueError("Malformed percent escape")
                # Check if the next two characters are valid hex digits
                try:
                    int(value[i+1:i+3], 16)
                except ValueError:
                    raise ValueError("Malformed percent escape")
                i += 3
            else:
                i += 1

    # Parse the query string
    parsed = parse_qs(value, keep_blank_values=True)

    # Return the last value for repeated keys
    return {key: values[-1] for key, values in parsed.items()}

